  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
  assert.deepEqual(parseEuros('12.345'), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES has correct values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(100000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 100000);
});

test('convert EUR to USD', () => {
  const result = convert(100000, 'USD');
  assert.equal(result.ok, true);
  const expected = Math.round((100000 / 100) * 1.085 * 100);
  assert.equal(result.value, expected);
});

test('convert EUR to GBP', () => {
  const result = convert(100000, 'GBP');
  assert.equal(result.ok, true);
  const expected = Math.round((100000 / 100) * 0.8425 * 100);
  assert.equal(result.value, expected);
});

test('convert small amounts EUR to USD', () => {
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  const expected = Math.round((100 / 100) * 1.085 * 100);
  assert.equal(result.value, expected);
});

test('convert zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert negative amount', () => {
  const result = convert(-100000, 'USD');
  assert.equal(result.ok, true);
  const expected = Math.round((-100000 / 100) * 1.085 * 100);
  assert.equal(result.value, expected);
});

test('convert unknown currency returns error', () => {
  const result = convert(100000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert unknown currency name', () => {
  const result = convert(100000, 'XYZ');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert maintains precision', () => {
  const result = convert(123456, 'USD');
  assert.equal(result.ok, true);
  const expected = Math.round((123456 / 100) * 1.085 * 100);
  assert.equal(result.value, expected);
});

test('formatMoney EUR format', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
  assert.equal(formatMoney(5, 'EUR'), '€0.05');
  assert.equal(formatMoney(100000000, 'EUR'), '€1,000,000.00');
});

test('formatMoney USD format', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
  assert.equal(formatMoney(5, 'USD'), '$0.05');
  assert.equal(formatMoney(100000000, 'USD'), '$1,000,000.00');
});

test('formatMoney GBP format', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
  assert.equal(formatMoney(5, 'GBP'), '£0.05');
  assert.equal(formatMoney(100000000, 'GBP'), '£1,000,000.00');
});

test('formatMoney with negative amounts EUR', () => {
  assert.equal(formatMoney(-250, 'EUR'), '-€2.50');
  assert.equal(formatMoney(-1000000, 'EUR'), '-€10,000.00');
});

test('formatMoney with negative amounts USD', () => {
  assert.equal(formatMoney(-250, 'USD'), '-$2.50');
  assert.equal(formatMoney(-1000000, 'USD'), '-$10,000.00');
});

test('formatMoney with negative amounts GBP', () => {
  assert.equal(formatMoney(-250, 'GBP'), '-£2.50');
  assert.equal(formatMoney(-1000000, 'GBP'), '-£10,000.00');
});

test('formatMoney zero amount', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('formatMoney includes thousands separator', () => {
  assert.equal(formatMoney(1234567, 'EUR'), '€12,345.67');
  assert.equal(formatMoney(1234567, 'USD'), '$12,345.67');
  assert.equal(formatMoney(1234567, 'GBP'), '£12,345.67');
});

test('formatMoney with single digit cents', () => {
  assert.equal(formatMoney(105, 'EUR'), '€1.05');
  assert.equal(formatMoney(105, 'USD'), '$1.05');
  assert.equal(formatMoney(105, 'GBP'), '£1.05');
});

test('formatMoney with unknown currency uses code', () => {
  assert.equal(formatMoney(123456, 'JPY'), 'JPY1,234.56');
